const assert = require('node:assert/strict');

const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

const baseDocs = [
  { id: 'a1', tenant: 'a', owner: 'alice', deleted: false, archived: false },
  { id: 'a2', tenant: 'a', owner: 'bob', deleted: false, archived: false },
  { id: 'b1', tenant: 'b', owner: 'alice', deleted: false, archived: false },
  { id: 'gone', tenant: 'a', owner: 'alice', deleted: true, archived: false },
  { id: 'done', tenant: 'a', owner: 'alice', deleted: false, archived: true },
];

function setup() {
  const repo = new DocumentRepository(baseDocs.map(d => ({ ...d })));
  return { repo, service: new DocumentService(repo) };
}

const admin = { tenant: 'a', user: 'alice', role: 'admin' };
const editorOwner = { tenant: 'a', user: 'alice', role: 'editor' };
const editorOther = { tenant: 'a', user: 'bob', role: 'editor' };
const viewer = { tenant: 'a', user: 'alice', role: 'viewer' };
const foreignAdmin = { tenant: 'b', user: 'x', role: 'admin' };

// Admin can archive any visible document in tenant.
{
  const { repo, service } = setup();
  service.archive(admin, 'a2');
  assert.equal(repo.documents[1].archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'alice', document: 'a2' }]);
}

// Editor can archive own document.
{
  const { repo, service } = setup();
  service.archive(editorOwner, 'a1');
  assert.equal(repo.documents[0].archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'alice', document: 'a1' }]);
}

// Editor cannot archive someone else's document: forbidden, no changes.
{
  const { repo, service } = setup();
  assert.throws(() => service.archive(editorOther, 'a1'), /forbidden/);
  assert.equal(repo.documents[0].archived, false);
  assert.deepEqual(repo.audit, []);
}

// Viewer can never archive: forbidden, no changes.
{
  const { repo, service } = setup();
  assert.throws(() => service.archive(viewer, 'a1'), /forbidden/);
  assert.equal(repo.documents[0].archived, false);
  assert.deepEqual(repo.audit, []);
}

// Missing, deleted, foreign-tenant: not found, even for admin; no changes.
for (const [actor, id] of [[admin, 'missing'], [admin, 'gone'], [admin, 'b1'], [foreignAdmin, 'a1'], [editorOwner, 'b1']]) {
  const { repo, service } = setup();
  assert.throws(() => service.archive(actor, id), /not found/);
  assert.deepEqual(repo.audit, []);
  assert.deepEqual(repo.documents.map(d => d.archived), baseDocs.map(d => d.archived));
}

// Already archived visible document: no-op with permission, forbidden without.
{
  const { repo, service } = setup();
  service.archive(admin, 'done');
  assert.equal(repo.documents[4].archived, true);
  assert.deepEqual(repo.audit, []);
}
{
  const { repo, service } = setup();
  assert.throws(() => service.archive(editorOther, 'done'), /forbidden/);
  assert.deepEqual(repo.audit, []);
}

console.log('auth checks passed');

